    function init(competitions) {
      competition = competitions;

      $(".spn-competition-description").text(competition.Description);

      dateFrom = new Date(competition.From);
      dateTo = new Date(competition.To);
      //dateFrom = new Date(2021, 10, 26, 0, 0, 0, 0);
      //dateTo = new Date(2021, 10, 28, 0, 0, 0, 0);
      var today = new Date();

      tournamentYear = dateFrom.getFullYear();
      tournamentMonth = dateFrom.getMonth() + 1;

      var checkDate = new Date(competition.From);
      checkDate.setDate(checkDate.getDate() - 28);
      if (today >= checkDate) {
        checkOrderOfGameAvailable();
      } else {
        $("#section_competition_order_of_game")
          .empty()
          .html("<span class='cc-value'>Non ancora disponibile.</span>");
      }

      checkDocuments();

      discipline = competition.Discipline;

      if (discipline.toUpperCase() == "TENNIS") {
        idDisciplina = 4332;
      }
      if (discipline.toUpperCase() == "PADEL") {
        idDisciplina = 172;
      }
      if (discipline.toUpperCase() == "BEACH TENNIS") {
        idDisciplina = 171;
      }
      if (discipline.toUpperCase() == "PICKLEBALL") {
        idDisciplina = 174;
      }

      if (competition.Status == "Approvato" && dateFrom <= today) {
        $(".spn-competition-status").addClass("cc-in-progress");
        $(".spn-competition-status .cc-svg").addClass(
          "cc-svg-tournament-in-progress"
        );
        $(".spn-competition-status .cc-value").text("IN CORSO");
      }
      if (competition.Status == "Approvato" && dateFrom > today) {
        $(".spn-competition-status").addClass("cc-in-scheduled");
        $(".spn-competition-status .cc-svg").addClass(
          "cc-svg-tournament-in-scheduled"
        );
        $(".spn-competition-status .cc-value").text("IN PROGRAMMA");
      }
      if (competition.Status == "Chiuso") {
        $(".spn-competition-status").addClass("cc-end");
        $(".spn-competition-status .cc-svg").addClass("cc-svg-tournament-end");
        $(".spn-competition-status .cc-value").text("CONCLUSO");
      }

      if (competition.CategoryAge != null) {
        var CategoryAge = competition.CategoryAge.split(",");
        $(".spn-competition-categoryage").text(
          CategoryAge[0] + " - " + CategoryAge[CategoryAge.length - 1]
