      $("#btnPhoneEdit").on("click", function () {
        if ($("input[name=frmPhone]").val().trim() == "") return false;
        var phoneCheck = $("input[name=frmPhone]").val().trim();
        //phoneCheck = phoneCheck.replaceAll(" ", "");
