        if (!$.isNumeric(phoneCheck)) {
          alert("Inserisci un numero di telefono valido");
          return false;
        }
        playerCheckSetPhone($("input[name=frmPhone]").val().trim()).then(
          function (res) {
            $("#popup").remove();
            switch (res.statusCode) {
              case 200:
                if (!doppio) subscribeToTournament(false);
                else checkSubscribeTemporaryToTournament();
                break;
              case 404:
                showPopUpSubscriptionError(res.error);
            }
          }
        );
      });
